/* strength-compass.html — translations of this page's text, matched by the English original (see i18n.js). */
I18N.phrases({
  "ORIGINAL STRENGTHS ASSESSMENT": { es: "EVALUACIÓN ORIGINAL DE FORTALEZAS", ar: "تقييم أصلي لنقاط القوة", zh: "原创优势评估", sw: "TATHMINI ASILIA YA UIMARA", sv: "EGEN STYRKEBEDÖMNING", de: "EIGENE STÄRKENANALYSE", pt: "AVALIAÇÃO ORIGINAL DE FORÇAS", fr: "ÉVALUATION ORIGINALE DES FORCES" },
  "Find the strengths that shape how you work.": { es: "Descubre las fortalezas que definen tu forma de trabajar.", ar: "اكتشف نقاط القوة التي تشكّل طريقة عملك.", zh: "发现塑造你工作方式的优势。", sw: "Gundua uimara unaounda jinsi unavyofanya kazi.", sv: "Hitta styrkorna som formar hur du arbetar.", de: "Finde die Stärken, die prägen, wie du arbeitest.", pt: "Descubra as forças que moldam seu jeito de trabalhar.", fr: "Trouvez les forces qui façonnent votre façon de travailler." },
  "Choose which of two positive statements feels more like you. Your report identifies five leading strengths from twelve original themes and shows how to use them productively.": { es: "Elige cuál de dos frases positivas se parece más a ti. Tu informe identifica cinco fortalezas principales de doce temas originales y muestra cómo aprovecharlas.", ar: "اختر أي العبارتين الإيجابيتين تشبهك أكثر. يحدد تقريرك خمس نقاط قوة رئيسية من اثني عشر محورًا أصليًا ويوضح كيف تستفيد منها.", zh: "在两条积极的陈述中选出更像你的那一条。报告会从十二个原创主题中找出你最突出的五项优势，并说明如何善用它们。", sw: "Chagua kauli ipi kati ya mbili chanya inakufanana zaidi. Ripoti yako inatambua nguvu tano kuu kutoka mada kumi na mbili asilia na kuonyesha jinsi ya kuzitumia vizuri.", sv: "Välj vilket av två positiva påståenden som liknar dig mest. Rapporten pekar ut fem ledande styrkor bland tolv egna teman och visar hur du använder dem väl.", de: "Wähle, welche von zwei positiven Aussagen eher zu dir passt. Dein Bericht ermittelt fünf führende Stärken aus zwölf eigenen Themen und zeigt, wie du sie produktiv nutzt.", pt: "Escolha qual de duas afirmações positivas parece mais com você. Seu relatório identifica cinco forças principais entre doze temas originais e mostra como usá-las bem.", fr: "Choisissez laquelle de deux affirmations positives vous ressemble le plus. Votre rapport identifie cinq forces principales parmi douze thèmes originaux et montre comment les utiliser." },
  "paired choices": { es: "elecciones por pares", ar: "اختيار ثنائي", zh: "组二选一", sw: "machaguo ya jozi", sv: "parvisa val", de: "Paarvergleiche", pt: "escolhas em pares", fr: "choix par paires" },
  "strength themes": { es: "temas de fortalezas", ar: "محورًا للقوة", zh: "个优势主题", sw: "mada za uimara", sv: "styrketeman", de: "Stärkenthemen", pt: "temas de força", fr: "thèmes de forces" },
  "Top 5": { es: "Top 5", ar: "أفضل 5", zh: "前 5 名", sw: "5 bora", sv: "Topp 5", de: "Top 5", pt: "Top 5", fr: "Top 5" },
  "personal report": { es: "informe personal", ar: "تقرير شخصي", zh: "个人报告", sw: "ripoti binafsi", sv: "personlig rapport", de: "persönlicher Bericht", pt: "relatório pessoal", fr: "rapport personnel" },
  "Choose honestly, not ideally.": { es: "Elige con sinceridad, no lo ideal.", ar: "اختر بصدق، لا بشكل مثالي.", zh: "如实选择，而不是理想化。", sw: "Chagua kwa uaminifu, si kwa ukamilifu.", sv: "Välj ärligt, inte idealiskt.", de: "Wähle ehrlich, nicht ideal.", pt: "Escolha com honestidade, não pelo ideal.", fr: "Choisissez honnêtement, pas idéalement." },
  "Both statements are intentionally positive. Select the one that describes your natural behaviour most often. This educational self-reflection tool is not a clinical personality assessment and is not affiliated with CliftonStrengths or Gallup.": { es: "Las dos frases son positivas a propósito. Elige la que describe tu comportamiento natural con más frecuencia. Esta herramienta educativa de autorreflexión no es una evaluación clínica de personalidad y no está afiliada a CliftonStrengths ni a Gallup.", ar: "العبارتان إيجابيتان عمدًا. اختر التي تصف سلوكك الطبيعي في أغلب الأحيان. أداة التأمل الذاتي التعليمية هذه ليست تقييمًا سريريًا للشخصية ولا ترتبط بـ CliftonStrengths أو Gallup.", zh: "两条陈述都刻意设计为积极的。选择最常描述你自然行为的那一条。这个教育性自我反思工具不是临床人格评估，与 CliftonStrengths 或 Gallup 无关。", sw: "Kauli zote mbili ni chanya kwa makusudi. Chagua inayoeleza tabia yako ya asili mara nyingi zaidi. Zana hii ya kielimu ya kujitafakari si tathmini ya kitabibu ya haiba na haihusiani na CliftonStrengths wala Gallup.", sv: "Båda påståendena är medvetet positiva. Välj det som oftast beskriver hur du naturligt beter dig. Det här lärande verktyget för självreflektion är inget kliniskt personlighetstest och har ingen koppling till CliftonStrengths eller Gallup.", de: "Beide Aussagen sind bewusst positiv. Wähle die, die dein natürliches Verhalten am häufigsten beschreibt. Dieses Werkzeug zur Selbstreflexion ist kein klinischer Persönlichkeitstest und steht in keiner Verbindung zu CliftonStrengths oder Gallup.", pt: "As duas afirmações são positivas de propósito. Escolha a que descreve seu comportamento natural com mais frequência. Esta ferramenta educativa de autorreflexão não é uma avaliação clínica de personalidade e não tem ligação com CliftonStrengths ou Gallup.", fr: "Les deux affirmations sont volontairement positives. Choisissez celle qui décrit le plus souvent votre comportement naturel. Cet outil éducatif d'introspection n'est pas une évaluation clinique de la personnalité et n'est pas affilié à CliftonStrengths ni à Gallup." },
  "Begin private assessment": { es: "Empezar la evaluación privada", ar: "ابدأ التقييم الخاص", zh: "开始私密评估", sw: "Anza tathmini ya faragha", sv: "Starta den privata bedömningen", de: "Private Analyse starten", pt: "Iniciar a avaliação privada", fr: "Commencer l'évaluation privée" },
  "Your choices and report remain in this browser. Nothing is uploaded or stored by MigaBuilder.": { es: "Tus elecciones y tu informe se quedan en este navegador. MigaBuilder no sube ni guarda nada.", ar: "تبقى اختياراتك وتقريرك في هذا المتصفح. لا يرفع MigaBuilder أو يخزن أي شيء.", zh: "你的选择和报告保留在此浏览器中。MigaBuilder 不会上传或保存任何内容。", sw: "Machaguo yako na ripoti yanabaki kwenye kivinjari hiki. MigaBuilder haipakii wala kuhifadhi chochote.", sv: "Dina val och din rapport stannar i den här webbläsaren. MigaBuilder laddar inte upp eller sparar något.", de: "Deine Antworten und dein Bericht bleiben in diesem Browser. MigaBuilder lädt nichts hoch und speichert nichts.", pt: "Suas escolhas e o relatório ficam neste navegador. O MigaBuilder não envia nem guarda nada.", fr: "Vos choix et votre rapport restent dans ce navigateur. MigaBuilder n'envoie ni ne stocke rien." },
  "Early Italian Renaissance (Proto-Renaissance)": { es: "Primer Renacimiento italiano (Protorrenacimiento)", ar: "عصر النهضة الإيطالي المبكر (ما قبل النهضة)", zh: "意大利早期文艺复兴（原文艺复兴）", sw: "Mwamko wa mapema wa Kiitaliano (kabla ya Mwamko)", sv: "Tidig italiensk renässans (protorenässans)", de: "Italienische Frührenaissance (Protorenaissance)", pt: "Primeiro Renascimento italiano (Proto-Renascimento)", fr: "Première Renaissance italienne (Proto-Renaissance)" },
  "A Florentine painter who broke from flat medieval icons and gave figures weight, emotion and real space, most famously in the Scrovegni Chapel frescoes in Padua.": { es: "Pintor florentino que rompió con los iconos medievales planos y dio a las figuras peso, emoción y espacio real, sobre todo en los frescos de la capilla de los Scrovegni en Padua.", ar: "رسام فلورنسي ابتعد عن الأيقونات القروسطية المسطحة ومنح شخصياته ثقلًا وعاطفة ومساحة حقيقية، أشهرها جداريات كنيسة سكروفيني في بادوا.", zh: "佛罗伦萨画家，突破了扁平的中世纪圣像，赋予人物重量、情感和真实空间，最著名的是帕多瓦斯克罗威尼礼拜堂的壁画。", sw: "Mchoraji wa Florence aliyeachana na sanamu bapa za zama za kati na kuwapa wahusika uzito, hisia na nafasi halisi, maarufu zaidi katika michoro ya ukutani ya Kanisa la Scrovegni huko Padua.", sv: "En florentinsk målare som bröt med platta medeltida ikoner och gav gestalterna tyngd, känsla och verkligt rum, mest känd för fresker i Scrovegnikapellet i Padua.", de: "Ein Florentiner Maler, der sich von flachen mittelalterlichen Ikonen löste und Figuren Gewicht, Gefühl und echten Raum gab, am berühmtesten in den Fresken der Scrovegni-Kapelle in Padua.", pt: "Um pintor florentino que rompeu com os ícones medievais chapados e deu às figuras peso, emoção e espaço real, sobretudo nos afrescos da Capela Scrovegni, em Pádua.", fr: "Un peintre florentin qui a rompu avec les icônes médiévales plates et donné aux figures poids, émotion et espace réel, surtout dans les fresques de la chapelle Scrovegni à Padoue." },
  "The deep lapis-blue ground, gilded arches and glowing gold halos echo his chapel frescoes. In front stands an original dragon drawn in the same colours, holding a star that fits this tool.": { es: "El profundo fondo azul lapislázuli, los arcos dorados y los halos de oro brillantes evocan sus frescos de la capilla. Delante hay un dragón original dibujado con los mismos colores, sosteniendo una estrella que encaja con esta herramienta.", ar: "الأرضية الزرقاء اللازوردية العميقة والأقواس المذهّبة والهالات الذهبية المتوهجة تستحضر جدارياته في الكنيسة. وأمامها تنين أصلي مرسوم بالألوان نفسها يحمل نجمة تناسب هذه الأداة.", zh: "深青金石蓝的底色、镀金拱门和闪耀的金色光环呼应了他的礼拜堂壁画。前面是一条用同样颜色绘制的原创龙，拿着一颗与本工具相配的星星。", sw: "Ardhi ya bluu ya lapis iliyokolea, matao ya dhahabu na duara za mwanga za dhahabu zinakumbusha michoro yake ya kanisani. Mbele kuna joka asilia aliyechorwa kwa rangi zilezile, akishika nyota inayofaa zana hii.", sv: "Den djupa lapisblå bakgrunden, de förgyllda valven och de lysande guldglorierna ekar hans kapellfresker. Framför står en egen drake i samma färger som håller en stjärna som passar verktyget.", de: "Der tiefe lapisblaue Grund, vergoldete Bögen und leuchtende goldene Heiligenscheine erinnern an seine Kapellenfresken. Davor steht ein eigener Drache in denselben Farben, der einen Stern hält, der zu diesem Werkzeug passt.", pt: "O fundo azul-lápis profundo, os arcos dourados e as auréolas de ouro brilhantes ecoam seus afrescos da capela. Na frente está um dragão original desenhado nas mesmas cores, segurando uma estrela que combina com esta ferramenta.", fr: "Le fond bleu lapis profond, les arcs dorés et les auréoles d'or lumineuses évoquent ses fresques de chapelle. Devant se tient un dragon original dessiné dans les mêmes couleurs, tenant une étoile qui convient à cet outil." },
  "Choice {0} of {1}": { es: "Elección {0} de {1}", ar: "الاختيار {0} من {1}", zh: "第 {0} 题，共 {1} 题", sw: "Chaguo {0} kati ya {1}", sv: "Val {0} av {1}", de: "Auswahl {0} von {1}", pt: "Escolha {0} de {1}", fr: "Choix {0} sur {1}" },
  "Which statement is more like you?": { es: "¿Qué frase se parece más a ti?", ar: "أي عبارة تشبهك أكثر؟", zh: "哪条陈述更像你？", sw: "Kauli ipi inakufanana zaidi?", sv: "Vilket påstående liknar dig mest?", de: "Welche Aussage passt eher zu dir?", pt: "Qual afirmação parece mais com você?", fr: "Quelle affirmation vous ressemble le plus ?" },
  "Strongly A": { es: "Claramente A", ar: "A بقوة", zh: "非常像 A", sw: "A kwa nguvu", sv: "Tydligt A", de: "Deutlich A", pt: "Claramente A", fr: "Nettement A" },
  "Slightly A": { es: "Un poco A", ar: "A قليلًا", zh: "有点像 A", sw: "A kidogo", sv: "Lite A", de: "Eher A", pt: "Um pouco A", fr: "Plutôt A" },
  "Both equally": { es: "Las dos por igual", ar: "الاثنتان بالتساوي", zh: "两者一样", sw: "Zote sawa", sv: "Båda lika", de: "Beide gleich", pt: "Os dois igualmente", fr: "Les deux également" },
  "Slightly B": { es: "Un poco B", ar: "B قليلًا", zh: "有点像 B", sw: "B kidogo", sv: "Lite B", de: "Eher B", pt: "Um pouco B", fr: "Plutôt B" },
  "Strongly B": { es: "Claramente B", ar: "B بقوة", zh: "非常像 B", sw: "B kwa nguvu", sv: "Tydligt B", de: "Deutlich B", pt: "Claramente B", fr: "Nettement B" },
  "YOUR STRENGTH COMPASS": { es: "TU BRÚJULA DE FORTALEZAS", ar: "بوصلة نقاط قوتك", zh: "你的优势罗盘", sw: "DIRA YAKO YA UIMARA", sv: "DIN STYRKEKOMPASS", de: "DEIN STÄRKENKOMPASS", pt: "SUA BÚSSOLA DE FORÇAS", fr: "VOTRE BOUSSOLE DES FORCES" },
  "Your top five strengths": { es: "Tus cinco fortalezas principales", ar: "نقاط قوتك الخمس الأبرز", zh: "你最突出的五项优势", sw: "Nguvu zako tano kuu", sv: "Dina fem främsta styrkor", de: "Deine fünf größten Stärken", pt: "Suas cinco maiores forças", fr: "Vos cinq forces principales" },
  "These themes describe where your attention and energy naturally went during this assessment. A lower score is not a weakness—it may simply be less instinctive for you.": { es: "Estos temas describen hacia dónde fueron de forma natural tu atención y tu energía durante esta evaluación. Una puntuación más baja no es una debilidad: puede que simplemente te salga menos de forma instintiva.", ar: "تصف هذه المحاور أين ذهب انتباهك وطاقتك بشكل طبيعي خلال هذا التقييم. الدرجة الأقل ليست ضعفًا — قد تكون ببساطة أقل فطرية لديك.", zh: "这些主题描述了在本次评估中你的注意力和精力自然流向何处。分数较低并不是弱点——可能只是对你来说不那么本能。", sw: "Mada hizi zinaeleza umakini na nguvu zako zilielekea wapi kiasili wakati wa tathmini hii. Alama ya chini si udhaifu — huenda tu si ya kisilika kwako.", sv: "De här temana beskriver var din uppmärksamhet och energi naturligt hamnade under bedömningen. Ett lägre värde är ingen svaghet — det kan bara vara mindre instinktivt för dig.", de: "Diese Themen beschreiben, wohin deine Aufmerksamkeit und Energie in dieser Analyse von selbst gingen. Ein niedrigerer Wert ist keine Schwäche — es liegt dir vielleicht nur weniger instinktiv.", pt: "Estes temas descrevem para onde sua atenção e energia foram naturalmente nesta avaliação. Uma nota mais baixa não é fraqueza — pode só ser menos instintivo para você.", fr: "Ces thèmes décrivent où votre attention et votre énergie sont naturellement allées pendant l'évaluation. Un score plus bas n'est pas une faiblesse — c'est peut-être simplement moins instinctif pour vous." },
  "All twelve themes": { es: "Los doce temas", ar: "المحاور الاثنا عشر", zh: "全部十二个主题", sw: "Mada zote kumi na mbili", sv: "Alla tolv teman", de: "Alle zwölf Themen", pt: "Todos os doze temas", fr: "Les douze thèmes" },
  "Print or save PDF": { es: "Imprimir o guardar PDF", ar: "اطبع أو احفظ PDF", zh: "打印或保存 PDF", sw: "Chapisha au hifadhi PDF", sv: "Skriv ut eller spara PDF", de: "Drucken oder als PDF speichern", pt: "Imprimir ou salvar PDF", fr: "Imprimer ou enregistrer en PDF" },
  "Take it again": { es: "Hacerlo de nuevo", ar: "أعد الاختبار", zh: "再测一次", sw: "Fanya tena", sv: "Gör om testet", de: "Noch einmal machen", pt: "Fazer de novo", fr: "Le refaire" },
  "This report is for reflection and development, not hiring, diagnosis or other high-stakes decisions. Results can change with context, experience and how you interpreted the statements.": { es: "Este informe es para reflexionar y crecer, no para contratar, diagnosticar ni tomar otras decisiones importantes. Los resultados pueden cambiar según el contexto, la experiencia y cómo interpretaste las frases.", ar: "هذا التقرير للتأمل والتطوير، لا للتوظيف أو التشخيص أو القرارات المصيرية. قد تتغير النتائج بحسب السياق والخبرة وطريقة فهمك للعبارات.", zh: "这份报告用于反思与成长，而非招聘、诊断或其他重大决定。结果会因情境、经历以及你对陈述的理解而变化。", sw: "Ripoti hii ni kwa kutafakari na kukua, si kwa kuajiri, uchunguzi wa kitabibu au maamuzi mengine mazito. Matokeo yanaweza kubadilika kulingana na muktadha, uzoefu na jinsi ulivyoelewa kauli.", sv: "Rapporten är till för reflektion och utveckling, inte rekrytering, diagnos eller andra viktiga beslut. Resultatet kan ändras med sammanhang, erfarenhet och hur du tolkade påståendena.", de: "Dieser Bericht dient der Reflexion und Entwicklung, nicht der Einstellung, Diagnose oder anderen folgenreichen Entscheidungen. Ergebnisse können sich je nach Kontext, Erfahrung und Deutung der Aussagen ändern.", pt: "Este relatório é para reflexão e desenvolvimento, não para contratação, diagnóstico ou outras decisões importantes. Os resultados podem mudar com o contexto, a experiência e como você interpretou as afirmações.", fr: "Ce rapport sert à la réflexion et au développement, pas au recrutement, au diagnostic ou à d'autres décisions à fort enjeu. Les résultats peuvent changer selon le contexte, l'expérience et votre interprétation des affirmations." },
  "Watch how Strength Compass works — with voice": { es: "Mira cómo funciona Strength Compass, con voz", ar: "شاهد كيف يعمل Strength Compass — مع صوت", zh: "观看 Strength Compass 的使用方法（带语音）", sw: "Tazama jinsi Strength Compass inavyofanya kazi — kwa sauti", sv: "Se hur Strength Compass fungerar — med röst", de: "Sieh dir an, wie Strength Compass funktioniert — mit Stimme", pt: "Veja como o Strength Compass funciona — com voz", fr: "Découvrez comment fonctionne Strength Compass — avec voix" },
  "Welcome to Strength Compass. It helps you discover the strengths that shape how you work.": { es: "Bienvenido a Strength Compass. Te ayuda a descubrir las fortalezas que definen tu forma de trabajar.", ar: "مرحبًا بك في Strength Compass. يساعدك على اكتشاف نقاط القوة التي تشكّل طريقة عملك.", zh: "欢迎使用 Strength Compass。它帮助你发现塑造你工作方式的优势。", sw: "Karibu Strength Compass. Inakusaidia kugundua uimara unaounda jinsi unavyofanya kazi.", sv: "Välkommen till Strength Compass. Den hjälper dig att hitta styrkorna som formar hur du arbetar.", de: "Willkommen bei Strength Compass. Es hilft dir, die Stärken zu entdecken, die prägen, wie du arbeitest.", pt: "Bem-vindo ao Strength Compass. Ele ajuda você a descobrir as forças que moldam seu jeito de trabalhar.", fr: "Bienvenue dans Strength Compass. Il vous aide à découvrir les forces qui façonnent votre façon de travailler." },
  "Press Begin. Each question shows two statements.": { es: "Pulsa Empezar. Cada pregunta muestra dos frases.", ar: "اضغط ابدأ. يعرض كل سؤال عبارتين.", zh: "点击开始。每道题都显示两条陈述。", sw: "Bonyeza Anza. Kila swali linaonyesha kauli mbili.", sv: "Tryck på Starta. Varje fråga visar två påståenden.", de: "Drück auf Starten. Jede Frage zeigt zwei Aussagen.", pt: "Aperte Começar. Cada pergunta mostra duas afirmações.", fr: "Appuyez sur Commencer. Chaque question montre deux affirmations." },
  "Choose which one sounds more like you, or both equally.": { es: "Elige cuál suena más a ti, o las dos por igual.", ar: "اختر أيهما يبدو أشبه بك، أو الاثنتين بالتساوي.", zh: "选择哪一条更像你，或两者一样。", sw: "Chagua ipi inasikika kama wewe zaidi, au zote sawa.", sv: "Välj vilket som låter mest som du, eller båda lika.", de: "Wähle, welche eher nach dir klingt, oder beide gleich.", pt: "Escolha qual soa mais como você, ou as duas igualmente.", fr: "Choisissez celle qui vous ressemble le plus, ou les deux à égalité." },
  "Your top five strengths appear with ideas for using them at work.": { es: "Tus cinco fortalezas principales aparecen con ideas para usarlas en el trabajo.", ar: "تظهر نقاط قوتك الخمس الأبرز مع أفكار لاستخدامها في العمل.", zh: "你最突出的五项优势会附上在工作中运用的建议。", sw: "Nguvu zako tano kuu zinaonekana pamoja na mawazo ya kuzitumia kazini.", sv: "Dina fem främsta styrkor visas med idéer för hur du använder dem i arbetet.", de: "Deine fünf größten Stärken erscheinen mit Ideen, wie du sie bei der Arbeit nutzt.", pt: "Suas cinco maiores forças aparecem com ideias para usá-las no trabalho.", fr: "Vos cinq forces principales apparaissent avec des idées pour les utiliser au travail." },
  "Now it is your turn. Open Strength Compass on MigaBuilder and try it yourself. It is free, and there is nothing to sign up for.": { es: "Ahora te toca a ti. Abre Strength Compass en MigaBuilder y pruébalo. Es gratis y no hace falta registrarse.", ar: "الآن جاء دورك. افتح Strength Compass على MigaBuilder وجرّبه بنفسك. إنه مجاني ولا يحتاج إلى تسجيل.", zh: "现在轮到你了。在 MigaBuilder 上打开 Strength Compass 亲自试试。它是免费的，无需注册。", sw: "Sasa ni zamu yako. Fungua Strength Compass kwenye MigaBuilder ujaribu mwenyewe. Ni bure, na hakuna haja ya kujisajili.", sv: "Nu är det din tur. Öppna Strength Compass på MigaBuilder och prova själv. Det är gratis och du behöver inte registrera dig.", de: "Jetzt bist du dran. Öffne Strength Compass auf MigaBuilder und probier es selbst. Es ist kostenlos, und du musst dich nirgends anmelden.", pt: "Agora é sua vez. Abra o Strength Compass no MigaBuilder e experimente. É grátis e não precisa de cadastro.", fr: "À vous maintenant. Ouvrez Strength Compass sur MigaBuilder et essayez vous-même. C'est gratuit, sans inscription." },
  "Welcome to Strength Compass. This walkthrough uses the real tool controls on this page.": { es: "Bienvenido a Strength Compass. Este recorrido usa los controles reales de la herramienta en esta página.", ar: "مرحبًا بك في Strength Compass. تستخدم هذه الجولة عناصر التحكم الحقيقية للأداة على هذه الصفحة.", zh: "欢迎使用 Strength Compass。本演示使用本页上真实的工具控件。", sw: "Karibu Strength Compass. Mwongozo huu unatumia vidhibiti halisi vya zana kwenye ukurasa huu.", sv: "Välkommen till Strength Compass. Genomgången använder verktygets riktiga kontroller på den här sidan.", de: "Willkommen bei Strength Compass. Diese Anleitung nutzt die echten Bedienelemente auf dieser Seite.", pt: "Bem-vindo ao Strength Compass. Este passo a passo usa os controles reais desta página.", fr: "Bienvenue dans Strength Compass. Ce guide utilise les vraies commandes de cette page." },
  "Art in the style of Giotto – click for more": { es: "Arte al estilo de Giotto: haz clic para saber más", ar: "رسم بأسلوب جوتو – انقر لمعرفة المزيد", zh: "乔托风格的插画——点击了解更多", sw: "Sanaa kwa mtindo wa Giotto – bofya kujua zaidi", sv: "Konst i Giottos stil – klicka för mer", de: "Kunst im Stil von Giotto – klicken für mehr", pt: "Arte no estilo de Giotto – clique para saber mais", fr: "Illustration dans le style de Giotto – cliquez pour en savoir plus" },
  "How to use Strength Compass": { es: "Cómo usar Strength Compass", ar: "كيفية استخدام Strength Compass", zh: "如何使用 Strength Compass", sw: "Jinsi ya kutumia Strength Compass", sv: "Så använder du Strength Compass", de: "So nutzt du Strength Compass", pt: "Como usar o Strength Compass", fr: "Comment utiliser Strength Compass" },
  "Strength Compass — Free Personality Strengths Test | MigaBuilder": { es: "Strength Compass — test gratuito de fortalezas personales | MigaBuilder", ar: "Strength Compass — اختبار مجاني لنقاط القوة الشخصية | MigaBuilder", zh: "Strength Compass — 免费个人优势测试 | MigaBuilder", sw: "Strength Compass — jaribio la bure la uimara wa haiba | MigaBuilder", sv: "Strength Compass — gratis test av personliga styrkor | MigaBuilder", de: "Strength Compass — kostenloser Persönlichkeits-Stärkentest | MigaBuilder", pt: "Strength Compass — teste grátis de forças da personalidade | MigaBuilder", fr: "Strength Compass — test gratuit des forces de personnalité | MigaBuilder" },
  "Strategic Vision": { es: "Visión estratégica", ar: "رؤية استراتيجية", zh: "战略眼光", sw: "Maono ya kimkakati", sv: "Strategisk vision", de: "Strategische Weitsicht", pt: "Visão estratégica", fr: "Vision stratégique" },
  "You naturally look ahead, notice possible paths and connect today's choices to tomorrow's outcomes.": { es: "Miras hacia delante de forma natural, ves caminos posibles y conectas las decisiones de hoy con los resultados de mañana.", ar: "تنظر إلى الأمام بطبيعتك، وتلاحظ المسارات الممكنة، وتربط خيارات اليوم بنتائج الغد.", zh: "你天生着眼未来，能看到可能的路径，并把今天的选择与明天的结果联系起来。", sw: "Kiasili unatazama mbele, unaona njia zinazowezekana na kuunganisha machaguo ya leo na matokeo ya kesho.", sv: "Du blickar naturligt framåt, ser möjliga vägar och kopplar dagens val till morgondagens resultat.", de: "Du blickst von selbst nach vorn, erkennst mögliche Wege und verbindest heutige Entscheidungen mit den Ergebnissen von morgen.", pt: "Você naturalmente olha para frente, percebe caminhos possíveis e liga as escolhas de hoje aos resultados de amanhã.", fr: "Vous regardez naturellement devant, repérez les chemins possibles et reliez les choix d'aujourd'hui aux résultats de demain." },
  "Before starting a project, describe the destination and two or three routes that could reach it.": { es: "Antes de empezar un proyecto, describe el destino y dos o tres rutas para llegar.", ar: "قبل بدء مشروع، صِف الوجهة وطريقين أو ثلاثة يمكن أن توصل إليها.", zh: "开始项目前，先描述目的地，以及两三条可以到达的路线。", sw: "Kabla ya kuanza mradi, eleza unakoenda na njia mbili au tatu za kufika huko.", sv: "Innan du startar ett projekt, beskriv målet och två eller tre vägar dit.", de: "Beschreibe vor einem Projekt das Ziel und zwei oder drei Wege, die dorthin führen könnten.", pt: "Antes de começar um projeto, descreva o destino e dois ou três caminhos para chegar lá.", fr: "Avant un projet, décrivez la destination et deux ou trois routes pour y arriver." },
  "Possibilities can multiply faster than decisions. Set a point when exploration ends and commitment begins.": { es: "Las posibilidades pueden multiplicarse más rápido que las decisiones. Fija un momento en que acaba la exploración y empieza el compromiso.", ar: "قد تتكاثر الاحتمالات أسرع من القرارات. حدد نقطة ينتهي عندها الاستكشاف ويبدأ الالتزام.", zh: "可能性的增长可能快过决策。设定一个时间点，结束探索，开始投入。", sw: "Uwezekano unaweza kuongezeka haraka kuliko maamuzi. Weka hatua ambapo uchunguzi unaisha na kujitoa kunaanza.", sv: "Möjligheterna kan växa snabbare än besluten. Bestäm när utforskandet slutar och åtagandet börjar.", de: "Möglichkeiten können sich schneller vermehren als Entscheidungen. Leg einen Punkt fest, an dem das Erkunden endet und die Festlegung beginnt.", pt: "As possibilidades podem se multiplicar mais rápido que as decisões. Defina um ponto em que a exploração acaba e o compromisso começa.", fr: "Les possibilités peuvent se multiplier plus vite que les décisions. Fixez le moment où l'exploration s'arrête et l'engagement commence." },
  "I naturally think several steps ahead.": { es: "De forma natural pienso varios pasos por delante.", ar: "أفكر بطبيعتي عدة خطوات إلى الأمام.", zh: "我天生会提前想好几步。", sw: "Kiasili nafikiri hatua kadhaa mbele.", sv: "Jag tänker naturligt flera steg framåt.", de: "Ich denke von selbst mehrere Schritte voraus.", pt: "Eu naturalmente penso vários passos à frente.", fr: "Je pense naturellement plusieurs coups à l'avance." },
  "I enjoy comparing different routes to a long-term goal.": { es: "Me gusta comparar distintas rutas hacia un objetivo a largo plazo.", ar: "أستمتع بمقارنة الطرق المختلفة نحو هدف بعيد المدى.", zh: "我喜欢比较实现长期目标的不同路径。", sw: "Ninafurahia kulinganisha njia tofauti kuelekea lengo la muda mrefu.", sv: "Jag gillar att jämföra olika vägar mot ett långsiktigt mål.", de: "Ich vergleiche gern verschiedene Wege zu einem langfristigen Ziel.", pt: "Gosto de comparar caminhos diferentes para uma meta de longo prazo.", fr: "J'aime comparer différentes routes vers un objectif à long terme." },
  "I quickly notice how today's choice may shape the future.": { es: "Noto enseguida cómo una decisión de hoy puede influir en el futuro.", ar: "ألاحظ بسرعة كيف قد يشكّل خيار اليوم المستقبل.", zh: "我很快就能看出今天的选择会如何影响未来。", sw: "Ninagundua haraka jinsi uchaguzi wa leo unavyoweza kuunda wakati ujao.", sv: "Jag ser snabbt hur dagens val kan forma framtiden.", de: "Ich merke schnell, wie eine heutige Entscheidung die Zukunft prägen kann.", pt: "Percebo rápido como a escolha de hoje pode moldar o futuro.", fr: "Je remarque vite comment un choix d'aujourd'hui peut façonner l'avenir." },
  "I feel energised when creating direction from uncertainty.": { es: "Me carga de energía crear un rumbo a partir de la incertidumbre.", ar: "أشعر بالحيوية عند صنع اتجاه من حالة عدم اليقين.", zh: "在不确定中开辟方向让我充满活力。", sw: "Ninapata nguvu ninapotengeneza mwelekeo kutoka kwa hali isiyo na uhakika.", sv: "Jag får energi av att skapa riktning ur osäkerhet.", de: "Es gibt mir Energie, aus Unsicherheit eine Richtung zu schaffen.", pt: "Fico cheio de energia ao criar direção a partir da incerteza.", fr: "Ça me donne de l'énergie de créer une direction à partir de l'incertitude." },
  "I often see possibilities before other people mention them.": { es: "A menudo veo posibilidades antes de que otros las mencionen.", ar: "كثيرًا ما أرى الاحتمالات قبل أن يذكرها الآخرون.", zh: "我常常在别人提到之前就看到可能性。", sw: "Mara nyingi naona uwezekano kabla wengine hawajautaja.", sv: "Jag ser ofta möjligheter innan andra nämner dem.", de: "Ich sehe oft Möglichkeiten, bevor andere sie erwähnen.", pt: "Muitas vezes vejo possibilidades antes que outros as mencionem.", fr: "Je vois souvent des possibilités avant que d'autres les mentionnent." },
  "Analytical Clarity": { es: "Claridad analítica", ar: "وضوح تحليلي", zh: "分析清晰", sw: "Uwazi wa kichambuzi", sv: "Analytisk skärpa", de: "Analytische Klarheit", pt: "Clareza analítica", fr: "Clarté analytique" },
  "You seek evidence, test assumptions and enjoy understanding why something works.": { es: "Buscas pruebas, pones a prueba los supuestos y disfrutas entendiendo por qué algo funciona.", ar: "تبحث عن الأدلة، وتختبر الافتراضات، وتستمتع بفهم سبب نجاح الشيء.", zh: "你寻求证据、检验假设，并乐于理解事物为何有效。", sw: "Unatafuta ushahidi, unajaribu dhana na kufurahia kuelewa kwa nini kitu kinafanya kazi.", sv: "Du söker belägg, prövar antaganden och tycker om att förstå varför något fungerar.", de: "Du suchst Belege, prüfst Annahmen und verstehst gern, warum etwas funktioniert.", pt: "Você busca evidências, testa suposições e gosta de entender por que algo funciona.", fr: "Vous cherchez des preuves, testez les hypothèses et aimez comprendre pourquoi quelque chose fonctionne." },
  "Analysis can delay action or sound colder than intended. Decide how much evidence is enough.": { es: "El análisis puede retrasar la acción o sonar más frío de lo que pretendes. Decide cuántas pruebas bastan.", ar: "قد يؤخر التحليل الفعل أو يبدو أبرد مما تقصد. حدد كم من الأدلة يكفي.", zh: "分析可能拖慢行动，或听起来比你本意更冷淡。先决定多少证据就足够。", sw: "Uchambuzi unaweza kuchelewesha hatua au kusikika baridi kuliko ulivyokusudia. Amua ushahidi kiasi gani unatosha.", sv: "Analys kan fördröja handling eller låta kallare än avsett. Bestäm hur mycket belägg som räcker.", de: "Analyse kann das Handeln verzögern oder kälter klingen als gewollt. Leg fest, wie viele Belege genug sind.", pt: "A análise pode atrasar a ação ou soar mais fria do que você quer. Decida quanta evidência basta.", fr: "L'analyse peut retarder l'action ou paraître plus froide que voulu. Décidez quelle quantité de preuves suffit." },
  "I like decisions to be supported by evidence.": { es: "Me gusta que las decisiones se apoyen en pruebas.", ar: "أحب أن تكون القرارات مدعومة بالأدلة.", zh: "我喜欢决策有证据支持。", sw: "Napenda maamuzi yaungwe mkono na ushahidi.", sv: "Jag vill att beslut ska stödjas av belägg.", de: "Ich mag Entscheidungen, die durch Belege gestützt sind.", pt: "Gosto de decisões apoiadas em evidências.", fr: "J'aime que les décisions soient appuyées par des preuves." },
  "I instinctively test whether an explanation is logically sound.": { es: "Compruebo por instinto si una explicación es lógicamente sólida.", ar: "أختبر بالفطرة ما إذا كان التفسير سليمًا منطقيًا.", zh: "我会本能地检验一个解释在逻辑上是否站得住脚。", sw: "Kwa silika najaribu kama maelezo yana mantiki thabiti.", sv: "Jag prövar instinktivt om en förklaring håller logiskt.", de: "Ich prüfe instinktiv, ob eine Erklärung logisch stimmt.", pt: "Testo por instinto se uma explicação faz sentido lógico.", fr: "Je vérifie d'instinct si une explication tient logiquement." },
  "I enjoy breaking complicated problems into smaller parts.": { es: "Disfruto dividiendo problemas complicados en partes más pequeñas.", ar: "أستمتع بتقسيم المشكلات المعقدة إلى أجزاء أصغر.", zh: "我喜欢把复杂问题拆成小块。", sw: "Ninafurahia kugawanya matatizo tata kuwa sehemu ndogo.", sv: "Jag tycker om att dela upp komplicerade problem i mindre delar.", de: "Ich zerlege gern komplizierte Probleme in kleinere Teile.", pt: "Gosto de dividir problemas complicados em partes menores.", fr: "J'aime découper les problèmes compliqués en parties plus petites." },
  "I notice inconsistencies that others may overlook.": { es: "Noto incoherencias que otros pueden pasar por alto.", ar: "ألاحظ تناقضات قد يغفل عنها الآخرون.", zh: "我能发现别人可能忽略的矛盾之处。", sw: "Ninagundua mikanganyiko ambayo wengine wanaweza kuipuuza.", sv: "Jag märker motsägelser som andra kan missa.", de: "Ich bemerke Widersprüche, die andere übersehen.", pt: "Noto inconsistências que outros podem deixar passar.", fr: "Je remarque des incohérences que d'autres peuvent manquer." },
  "I prefer to understand why something works before trusting it.": { es: "Prefiero entender por qué algo funciona antes de confiar en ello.", ar: "أفضّل فهم سبب نجاح الشيء قبل الوثوق به.", zh: "在信任某样东西之前，我更想先弄懂它为何有效。", sw: "Napendelea kuelewa kwa nini kitu kinafanya kazi kabla ya kukiamini.", sv: "Jag vill förstå varför något fungerar innan jag litar på det.", de: "Ich verstehe lieber, warum etwas funktioniert, bevor ich ihm vertraue.", pt: "Prefiro entender por que algo funciona antes de confiar nele.", fr: "Je préfère comprendre pourquoi quelque chose fonctionne avant de m'y fier." },
  "Creative Exploration": { es: "Exploración creativa", ar: "استكشاف إبداعي", zh: "创意探索", sw: "Uchunguzi wa ubunifu", sv: "Kreativt utforskande", de: "Kreatives Erkunden", pt: "Exploração criativa", fr: "Exploration créative" },
  "You generate fresh connections and enjoy turning unusual ideas into possibilities.": { es: "Generas conexiones nuevas y disfrutas convirtiendo ideas inusuales en posibilidades.", ar: "تولّد روابط جديدة وتستمتع بتحويل الأفكار غير المألوفة إلى احتمالات.", zh: "你能产生新的联想，并乐于把不寻常的想法变成可能。", sw: "Unazalisha miunganiko mipya na kufurahia kugeuza mawazo ya ajabu kuwa uwezekano.", sv: "Du skapar nya kopplingar och tycker om att göra ovanliga idéer till möjligheter.", de: "Du findest neue Verbindungen und machst gern aus ungewöhnlichen Ideen Möglichkeiten.", pt: "Você gera conexões novas e gosta de transformar ideias incomuns em possibilidades.", fr: "Vous créez des liens nouveaux et aimez transformer des idées inhabituelles en possibilités." },
  "Capture ideas quickly, then select one using a clear usefulness test.": { es: "Apunta las ideas rápido y después elige una con una prueba clara de utilidad.", ar: "دوّن الأفكار بسرعة، ثم اختر واحدة باختبار واضح للفائدة.", zh: "快速记下想法，再用明确的实用性标准选出一个。", sw: "Nasa mawazo haraka, kisha chagua moja kwa kipimo wazi cha manufaa.", sv: "Fånga idéer snabbt och välj sedan en med ett tydligt nyttotest.", de: "Halte Ideen schnell fest und wähle dann eine mit einem klaren Nützlichkeitstest.", pt: "Anote as ideias rápido e depois escolha uma com um teste claro de utilidade.", fr: "Notez vite les idées, puis choisissez-en une avec un test d'utilité clair." },
  "New ideas can distract from finishing. Keep a separate idea list so current work remains protected.": { es: "Las ideas nuevas pueden distraer de terminar. Ten una lista aparte de ideas para proteger el trabajo actual.", ar: "قد تشتت الأفكار الجديدة عن الإنجاز. احتفظ بقائمة أفكار منفصلة لحماية العمل الحالي.", zh: "新想法可能让你分心而做不完。另建一个想法清单，保护手头的工作。", sw: "Mawazo mapya yanaweza kuvuruga kukamilisha. Weka orodha tofauti ya mawazo ili kazi ya sasa ilindwe.", sv: "Nya idéer kan distrahera från att bli klar. Ha en separat idélista så att det pågående arbetet skyddas.", de: "Neue Ideen können vom Fertigstellen ablenken. Führe eine eigene Ideenliste, damit die aktuelle Arbeit geschützt bleibt.", pt: "Ideias novas podem distrair da finalização. Mantenha uma lista separada de ideias para proteger o trabalho atual.", fr: "Les nouvelles idées peuvent détourner de la finition. Tenez une liste d'idées à part pour protéger le travail en cours." },
  "Unexpected connections often give me useful ideas.": { es: "Las conexiones inesperadas suelen darme ideas útiles.", ar: "كثيرًا ما تمنحني الروابط غير المتوقعة أفكارًا مفيدة.", zh: "意想不到的联系常常给我有用的点子。", sw: "Miunganiko isiyotarajiwa mara nyingi hunipa mawazo muhimu.", sv: "Oväntade kopplingar ger mig ofta användbara idéer.", de: "Unerwartete Verbindungen geben mir oft nützliche Ideen.", pt: "Conexões inesperadas muitas vezes me dão ideias úteis.", fr: "Des liens inattendus me donnent souvent des idées utiles." },
  "I enjoy imagining approaches that have not been tried.": { es: "Disfruto imaginando enfoques que nadie ha probado.", ar: "أستمتع بتخيل أساليب لم تُجرَّب.", zh: "我喜欢设想没人试过的方法。", sw: "Ninafurahia kufikiria njia ambazo hazijajaribiwa.", sv: "Jag tycker om att föreställa mig sätt som ingen har provat.", de: "Ich stelle mir gern Ansätze vor, die noch niemand versucht hat.", pt: "Gosto de imaginar abordagens que ainda não foram tentadas.", fr: "J'aime imaginer des approches jamais essayées." },
  "I become energised when a problem has many possible answers.": { es: "Me carga de energía que un problema tenga muchas respuestas posibles.", ar: "أشعر بالحيوية عندما يكون للمشكلة إجابات محتملة كثيرة.", zh: "当一个问题有很多可能答案时，我会充满干劲。", sw: "Ninapata nguvu tatizo linapokuwa na majibu mengi yanayowezekana.", sv: "Jag får energi när ett problem har många möjliga svar.", de: "Ich bekomme Energie, wenn ein Problem viele mögliche Antworten hat.", pt: "Fico cheio de energia quando um problema tem muitas respostas possíveis.", fr: "Je suis plein d'énergie quand un problème a beaucoup de réponses possibles." },
  "I like transforming an ordinary concept into something distinctive.": { es: "Me gusta transformar un concepto corriente en algo distintivo.", ar: "أحب تحويل فكرة عادية إلى شيء مميز.", zh: "我喜欢把普通的概念变得与众不同。", sw: "Napenda kugeuza dhana ya kawaida kuwa kitu cha kipekee.", sv: "Jag gillar att förvandla ett vardagligt koncept till något särpräglat.", de: "Ich verwandle gern ein gewöhnliches Konzept in etwas Unverwechselbares.", pt: "Gosto de transformar um conceito comum em algo marcante.", fr: "J'aime transformer un concept ordinaire en quelque chose de distinctif." },
  "I naturally question whether there is a more inventive way.": { es: "De forma natural me pregunto si hay una manera más ingeniosa.", ar: "أتساءل بطبيعتي إن كانت هناك طريقة أكثر ابتكارًا.", zh: "我总会自然地思考有没有更有创意的办法。", sw: "Kiasili najiuliza kama kuna njia ya kibunifu zaidi.", sv: "Jag undrar naturligt om det finns ett mer uppfinningsrikt sätt.", de: "Ich frage mich von selbst, ob es einen erfinderischeren Weg gibt.", pt: "Naturalmente me pergunto se há um jeito mais inventivo.", fr: "Je me demande naturellement s'il existe une façon plus inventive." },
  "Reliable Execution": { es: "Ejecución fiable", ar: "تنفيذ موثوق", zh: "可靠执行", sw: "Utekelezaji wa kutegemewa", sv: "Pålitligt genomförande", de: "Verlässliche Umsetzung", pt: "Execução confiável", fr: "Exécution fiable" },
  "You create structure, follow through and gain satisfaction from completing what matters.": { es: "Creas estructura, cumples y te satisface terminar lo que importa.", ar: "تبني التنظيم، وتتابع حتى النهاية، وتشعر بالرضا عند إنجاز المهم.", zh: "你建立结构、贯彻到底，并从完成重要的事中获得满足。", sw: "Unaunda mpangilio, unakamilisha na kuridhika kwa kumaliza yaliyo muhimu.", sv: "Du skapar struktur, fullföljer och känner tillfredsställelse av att slutföra det som är viktigt.", de: "Du schaffst Struktur, ziehst Dinge durch und findest Befriedigung darin, Wichtiges abzuschließen.", pt: "Você cria estrutura, vai até o fim e se satisfaz em concluir o que importa.", fr: "Vous créez de la structure, allez jusqu'au bout et êtes satisfait de terminer ce qui compte." },
  "Turn goals into visible next actions, owners and finish dates.": { es: "Convierte los objetivos en próximos pasos visibles, responsables y fechas de entrega.", ar: "حوّل الأهداف إلى خطوات تالية واضحة ومسؤولين ومواعيد إنجاز.", zh: "把目标变成看得见的下一步行动、负责人和完成日期。", sw: "Geuza malengo kuwa hatua zinazofuata zinazoonekana, wahusika na tarehe za kukamilisha.", sv: "Gör om mål till synliga nästa steg, ansvariga och slutdatum.", de: "Mach aus Zielen sichtbare nächste Schritte, Verantwortliche und Termine.", pt: "Transforme metas em próximas ações visíveis, responsáveis e prazos.", fr: "Transformez les objectifs en prochaines actions visibles, avec responsables et échéances." },
  "Completion can become rigidity. Recheck whether the original plan still serves the goal.": { es: "Terminar puede volverse rigidez. Revisa si el plan original sigue sirviendo al objetivo.", ar: "قد يتحول الإنجاز إلى جمود. أعد التحقق مما إذا كانت الخطة الأصلية ما زالت تخدم الهدف.", zh: "坚持完成可能变成僵化。重新检查原计划是否仍服务于目标。", sw: "Kukamilisha kunaweza kuwa ugumu. Kagua tena kama mpango wa awali bado unatumikia lengo.", sv: "Att slutföra kan bli stelhet. Kontrollera om den ursprungliga planen fortfarande tjänar målet.", de: "Durchziehen kann zu Starrheit werden. Prüf erneut, ob der ursprüngliche Plan dem Ziel noch dient.", pt: "Concluir pode virar rigidez. Confira se o plano original ainda serve à meta.", fr: "Finir peut devenir de la rigidité. Revérifiez si le plan initial sert encore l'objectif." },
  "People can rely on me to finish what I commit to.": { es: "La gente puede confiar en que termino lo que me comprometo a hacer.", ar: "يمكن للناس الاعتماد عليّ لإنجاز ما ألتزم به.", zh: "大家可以放心，我承诺的事一定会完成。", sw: "Watu wanaweza kunitegemea kukamilisha ninachoahidi.", sv: "Folk kan lita på att jag gör klart det jag åtar mig.", de: "Andere können sich darauf verlassen, dass ich beende, was ich zusage.", pt: "As pessoas podem contar comigo para terminar o que prometo.", fr: "On peut compter sur moi pour finir ce que je promets." },
  "I naturally turn goals into concrete next steps.": { es: "De forma natural convierto los objetivos en pasos concretos.", ar: "أحوّل الأهداف بطبيعتي إلى خطوات تالية ملموسة.", zh: "我会自然地把目标变成具体的下一步。", sw: "Kiasili nageuza malengo kuwa hatua halisi zinazofuata.", sv: "Jag gör naturligt om mål till konkreta nästa steg.", de: "Ich mache aus Zielen von selbst konkrete nächste Schritte.", pt: "Naturalmente transformo metas em próximos passos concretos.", fr: "Je transforme naturellement les objectifs en étapes concrètes." },
  "I feel satisfied when work is organised and completed.": { es: "Me siento satisfecho cuando el trabajo está organizado y terminado.", ar: "أشعر بالرضا عندما يكون العمل منظمًا ومنجزًا.", zh: "当工作井井有条并完成时，我会感到满足。", sw: "Ninaridhika kazi inapopangwa na kukamilika.", sv: "Jag känner mig nöjd när arbetet är organiserat och klart.", de: "Ich bin zufrieden, wenn Arbeit geordnet und erledigt ist.", pt: "Fico satisfeito quando o trabalho está organizado e concluído.", fr: "Je suis satisfait quand le travail est organisé et terminé." },
  "I keep track of details that protect a result from falling apart.": { es: "Llevo el control de los detalles que evitan que un resultado se desmorone.", ar: "أتابع التفاصيل التي تحمي النتيجة من الانهيار.", zh: "我会盯住那些能防止结果崩溃的细节。", sw: "Ninafuatilia maelezo yanayolinda matokeo yasivunjike.", sv: "Jag håller koll på detaljer som hindrar ett resultat från att falla isär.", de: "Ich behalte Details im Blick, die ein Ergebnis vor dem Zerfallen schützen.", pt: "Acompanho detalhes que impedem um resultado de desmoronar.", fr: "Je garde l'œil sur les détails qui empêchent un résultat de s'effondrer." },
  "I prefer steady progress over last-minute improvisation.": { es: "Prefiero el progreso constante a la improvisación de última hora.", ar: "أفضّل التقدم الثابت على الارتجال في اللحظة الأخيرة.", zh: "比起临时抱佛脚，我更喜欢稳步推进。", sw: "Napendelea maendeleo ya polepole badala ya kubuni dakika za mwisho.", sv: "Jag föredrar stadiga framsteg framför improvisation i sista minuten.", de: "Ich mag stetigen Fortschritt lieber als Improvisation in letzter Minute.", pt: "Prefiro progresso constante a improviso de última hora.", fr: "Je préfère un progrès régulier à l'improvisation de dernière minute." },
  "Adaptive Momentum": { es: "Impulso adaptativo", ar: "زخم متكيّف", zh: "灵活应变", sw: "Kasi ya kujirekebisha", sv: "Anpassningsförmåga", de: "Anpassungsfähiger Schwung", pt: "Impulso adaptável", fr: "Élan adaptatif" },
  "You remain responsive when conditions change and can work effectively without a perfect map.": { es: "Sigues respondiendo cuando cambian las condiciones y puedes trabajar bien sin un mapa perfecto.", ar: "تبقى متجاوبًا عندما تتغير الظروف ويمكنك العمل بفعالية دون خريطة مثالية.", zh: "条件变化时你依然反应灵敏，没有完美地图也能高效工作。", sw: "Unabaki ukiitikia hali zinapobadilika na unaweza kufanya kazi kwa ufanisi bila ramani kamili.", sv: "Du förblir lyhörd när förutsättningarna ändras och kan arbeta effektivt utan en perfekt karta.", de: "Du bleibst reaktionsfähig, wenn sich Bedingungen ändern, und kannst ohne perfekte Karte gut arbeiten.", pt: "Você continua responsivo quando as condições mudam e trabalha bem sem um mapa perfeito.", fr: "Vous restez réactif quand les conditions changent et travaillez efficacement sans carte parfaite." },
  "Constant adjustment can make direction unclear. Protect a few non-negotiable priorities.": { es: "El ajuste constante puede volver confuso el rumbo. Protege unas pocas prioridades innegociables.", ar: "قد يجعل التعديل المستمر الاتجاه غير واضح. احمِ بضع أولويات غير قابلة للتفاوض.", zh: "不断调整可能让方向变模糊。守住几个不可妥协的优先事项。", sw: "Kurekebisha kila mara kunaweza kufanya mwelekeo usiwe wazi. Linda vipaumbele vichache visivyojadilika.", sv: "Ständig justering kan göra riktningen otydlig. Skydda några få prioriteringar som inte är förhandlingsbara.", de: "Ständiges Anpassen kann die Richtung unklar machen. Schütze ein paar nicht verhandelbare Prioritäten.", pt: "Ajustes constantes podem deixar a direção confusa. Proteja algumas prioridades inegociáveis.", fr: "L'ajustement permanent peut brouiller la direction. Protégez quelques priorités non négociables." },
  "I adjust quickly when circumstances change.": { es: "Me adapto rápido cuando cambian las circunstancias.", ar: "أتكيّف بسرعة عندما تتغير الظروف.", zh: "情况变化时我能迅速调整。", sw: "Ninajirekebisha haraka hali zinapobadilika.", sv: "Jag anpassar mig snabbt när omständigheterna ändras.", de: "Ich passe mich schnell an, wenn sich Umstände ändern.", pt: "Me ajusto rápido quando as circunstâncias mudam.", fr: "Je m'adapte vite quand les circonstances changent." },
  "I can make useful progress without having every detail settled.": { es: "Puedo avanzar de forma útil sin tener todos los detalles resueltos.", ar: "يمكنني تحقيق تقدم مفيد دون حسم كل التفاصيل.", zh: "即使细节没全部定下来，我也能取得有用的进展。", sw: "Ninaweza kupiga hatua yenye manufaa bila kila jambo kukamilishwa.", sv: "Jag kan komma framåt utan att varje detalj är klar.", de: "Ich komme gut voran, auch wenn nicht jedes Detail geklärt ist.", pt: "Consigo avançar bem sem ter todos os detalhes resolvidos.", fr: "Je progresse utilement sans que chaque détail soit réglé." },
  "Unexpected events often bring out my resourcefulness.": { es: "Los imprevistos suelen sacar mi ingenio.", ar: "كثيرًا ما تُظهر الأحداث غير المتوقعة براعتي.", zh: "意外事件往往能激发我的机智。", sw: "Matukio yasiyotarajiwa mara nyingi huibua ubunifu wangu.", sv: "Oväntade händelser lockar ofta fram min påhittighet.", de: "Unerwartete Ereignisse wecken oft meinen Einfallsreichtum.", pt: "Eventos inesperados costumam despertar minha criatividade prática.", fr: "Les imprévus révèlent souvent ma débrouillardise." },
  "I am comfortable revising a plan when new information appears.": { es: "Me siento cómodo revisando un plan cuando aparece información nueva.", ar: "أرتاح لتعديل الخطة عند ظهور معلومات جديدة.", zh: "有新信息时，我乐于修改计划。", sw: "Ninastarehe kurekebisha mpango taarifa mpya zinapojitokeza.", sv: "Jag har inget emot att ändra en plan när ny information dyker upp.", de: "Ich überarbeite einen Plan gern, wenn neue Informationen auftauchen.", pt: "Fico à vontade revisando um plano quando surgem informações novas.", fr: "Je suis à l'aise pour réviser un plan quand de nouvelles informations arrivent." },
  "I recover my momentum quickly after disruption.": { es: "Recupero el impulso rápido tras una interrupción.", ar: "أستعيد زخمي بسرعة بعد أي انقطاع.", zh: "被打断后我能很快重新找回节奏。", sw: "Ninarudisha kasi yangu haraka baada ya usumbufu.", sv: "Jag återfår snabbt farten efter en störning.", de: "Ich finde nach einer Störung schnell wieder in Schwung.", pt: "Retomo o ritmo rápido depois de uma interrupção.", fr: "Je retrouve vite mon élan après une perturbation." },
  "Bold Initiative": { es: "Iniciativa audaz", ar: "مبادرة جريئة", zh: "大胆主动", sw: "Ujasiri wa kuanzisha", sv: "Djärvt initiativ", de: "Mutige Initiative", pt: "Iniciativa ousada", fr: "Initiative audacieuse" },
  "You prefer beginning, experimenting and creating movement rather than waiting for certainty.": { es: "Prefieres empezar, experimentar y crear movimiento en lugar de esperar certezas.", ar: "تفضّل البدء والتجريب وصنع الحركة بدلًا من انتظار اليقين.", zh: "你更愿意开始、尝试和推动事情，而不是等待确定。", sw: "Unapendelea kuanza, kujaribu na kuleta msukumo badala ya kusubiri uhakika.", sv: "Du föredrar att börja, experimentera och skapa rörelse framför att vänta på visshet.", de: "Du fängst lieber an, experimentierst und bringst Bewegung, statt auf Gewissheit zu warten.", pt: "Você prefere começar, experimentar e criar movimento a esperar por certeza.", fr: "Vous préférez commencer, expérimenter et créer du mouvement plutôt qu'attendre la certitude." },
  "Define the smallest reversible first move and make it promptly.": { es: "Define el primer paso más pequeño y reversible, y dalo enseguida.", ar: "حدد أصغر خطوة أولى قابلة للتراجع، واتخذها فورًا.", zh: "确定最小、可撤回的第一步，并立即行动。", sw: "Fafanua hatua ndogo kabisa ya kwanza inayoweza kurudishwa, na uichukue mara moja.", sv: "Bestäm det minsta första steget som går att ångra och ta det direkt.", de: "Leg den kleinsten umkehrbaren ersten Schritt fest und mach ihn sofort.", pt: "Defina o menor primeiro passo reversível e dê logo.", fr: "Définissez le plus petit premier pas réversible et faites-le rapidement." },
  "Speed can leave others behind or skip useful preparation. Pause briefly for consequences and alignment.": { es: "La velocidad puede dejar atrás a otros o saltarse una preparación útil. Haz una breve pausa para pensar en las consecuencias y en el acuerdo.", ar: "قد تترك السرعة الآخرين خلفك أو تتخطى تحضيرًا مفيدًا. توقف قليلًا للتفكير في العواقب والتوافق.", zh: "速度太快可能把别人甩在后面，或跳过有用的准备。稍作停顿，考虑后果和共识。", sw: "Kasi inaweza kuwaacha wengine nyuma au kuruka maandalizi muhimu. Simama kidogo kufikiria matokeo na mapatano.", sv: "Fart kan lämna andra efter eller hoppa över nyttiga förberedelser. Stanna kort för konsekvenser och samsyn.", de: "Tempo kann andere zurücklassen oder nützliche Vorbereitung überspringen. Halte kurz inne für Folgen und Abstimmung.", pt: "A pressa pode deixar os outros para trás ou pular preparação útil. Pare um pouco para pensar nas consequências e no alinhamento.", fr: "La vitesse peut laisser les autres derrière ou sauter une préparation utile. Prenez une courte pause pour les conséquences et l'alignement." },
  "I would rather begin and learn than wait for perfect certainty.": { es: "Prefiero empezar y aprender a esperar una certeza perfecta.", ar: "أفضّل البدء والتعلم على انتظار يقين تام.", zh: "我宁愿先开始再学习，也不愿等待完全确定。", sw: "Napendelea kuanza na kujifunza kuliko kusubiri uhakika kamili.", sv: "Jag börjar hellre och lär mig än väntar på perfekt visshet.", de: "Ich fange lieber an und lerne, als auf perfekte Gewissheit zu warten.", pt: "Prefiro começar e aprender a esperar por certeza perfeita.", fr: "Je préfère commencer et apprendre plutôt qu'attendre une certitude parfaite." },
  "I naturally create momentum when a group is stuck.": { es: "De forma natural genero impulso cuando un grupo está atascado.", ar: "أصنع الزخم بطبيعتي عندما تتعثر المجموعة.", zh: "团队陷入僵局时，我会自然地推动大家前进。", sw: "Kiasili naleta msukumo kikundi kinapokwama.", sv: "Jag skapar naturligt fart när en grupp har kört fast.", de: "Ich bringe von selbst Schwung, wenn eine Gruppe feststeckt.", pt: "Naturalmente crio movimento quando um grupo empaca.", fr: "Je crée naturellement de l'élan quand un groupe est bloqué." },
  "I am comfortable taking the first visible step.": { es: "Me siento cómodo dando el primer paso visible.", ar: "أرتاح لاتخاذ الخطوة الأولى الظاهرة.", zh: "我乐于迈出看得见的第一步。", sw: "Ninastarehe kuchukua hatua ya kwanza inayoonekana.", sv: "Jag tar gärna det första synliga steget.", de: "Ich mache gern den ersten sichtbaren Schritt.", pt: "Fico à vontade dando o primeiro passo visível.", fr: "Je suis à l'aise pour faire le premier pas visible." },
  "I often turn conversation into action.": { es: "A menudo convierto la conversación en acción.", ar: "كثيرًا ما أحوّل الحديث إلى فعل.", zh: "我常常把讨论变成行动。", sw: "Mara nyingi nageuza mazungumzo kuwa vitendo.", sv: "Jag gör ofta om samtal till handling.", de: "Ich mache oft aus Gesprächen Taten.", pt: "Muitas vezes transformo conversa em ação.", fr: "Je transforme souvent la discussion en action." },
  "I enjoy testing an idea in the real world.": { es: "Disfruto probando una idea en el mundo real.", ar: "أستمتع باختبار فكرة في العالم الحقيقي.", zh: "我喜欢在现实中检验一个想法。", sw: "Ninafurahia kujaribu wazo katika ulimwengu halisi.", sv: "Jag tycker om att testa en idé i verkligheten.", de: "Ich teste gern eine Idee in der echten Welt.", pt: "Gosto de testar uma ideia no mundo real.", fr: "J'aime tester une idée dans le monde réel." },
  "Collaborative Builder": { es: "Constructor colaborativo", ar: "بانٍ متعاون", zh: "协作建设者", sw: "Mjenzi wa ushirikiano", sv: "Samarbetsbyggare", de: "Gemeinschaftlicher Gestalter", pt: "Construtor colaborativo", fr: "Bâtisseur collaboratif" },
  "You notice how people can contribute together and work to create shared ownership.": { es: "Ves cómo las personas pueden contribuir juntas y trabajas para crear un sentido de propiedad compartido.", ar: "تلاحظ كيف يمكن للناس أن يساهموا معًا وتعمل على بناء ملكية مشتركة.", zh: "你能看出大家如何共同贡献，并努力营造共同的归属感。", sw: "Unatambua jinsi watu wanavyoweza kuchangia pamoja na kufanya kazi kuunda umiliki wa pamoja.", sv: "Du ser hur människor kan bidra tillsammans och arbetar för ett gemensamt ägarskap.", de: "Du siehst, wie Menschen gemeinsam beitragen können, und arbeitest an gemeinsamer Verantwortung.", pt: "Você percebe como as pessoas podem contribuir juntas e trabalha para criar um senso de dono compartilhado.", fr: "Vous voyez comment les gens peuvent contribuer ensemble et travaillez à une appropriation partagée." },
  "Clarify the common goal, then invite each person to contribute where they are strongest.": { es: "Aclara el objetivo común y luego invita a cada persona a contribuir donde es más fuerte.", ar: "وضّح الهدف المشترك، ثم ادعُ كل شخص للمساهمة حيث يكون أقوى.", zh: "先明确共同目标，再邀请每个人在自己最擅长的地方贡献力量。", sw: "Fafanua lengo la pamoja, kisha mwalike kila mtu kuchangia pale alipo imara zaidi.", sv: "Tydliggör det gemensamma målet och bjud sedan in var och en att bidra där de är starkast.", de: "Kläre das gemeinsame Ziel und lade dann jeden ein, dort beizutragen, wo er am stärksten ist.", pt: "Deixe claro o objetivo comum e convide cada pessoa a contribuir onde é mais forte.", fr: "Clarifiez l'objectif commun, puis invitez chacun à contribuer là où il est le plus fort." },
  "Consensus can become more important than clarity. Some decisions still need a clear owner.": { es: "El consenso puede volverse más importante que la claridad. Algunas decisiones siguen necesitando un responsable claro.", ar: "قد يصبح الإجماع أهم من الوضوح. بعض القرارات ما زالت تحتاج إلى مسؤول واضح.", zh: "共识可能变得比清晰更重要。有些决定仍需要一个明确的负责人。", sw: "Maafikiano yanaweza kuwa muhimu kuliko uwazi. Baadhi ya maamuzi bado yanahitaji mhusika wazi.", sv: "Konsensus kan bli viktigare än tydlighet. Vissa beslut behöver fortfarande en tydlig ägare.", de: "Konsens kann wichtiger werden als Klarheit. Manche Entscheidungen brauchen trotzdem eine klare verantwortliche Person.", pt: "O consenso pode ficar mais importante que a clareza. Algumas decisões ainda precisam de um responsável claro.", fr: "Le consensus peut devenir plus important que la clarté. Certaines décisions ont quand même besoin d'un responsable clair." },
  "I naturally look for ways people can succeed together.": { es: "De forma natural busco maneras de que la gente tenga éxito junta.", ar: "أبحث بطبيعتي عن طرق لينجح الناس معًا.", zh: "我会自然地寻找让大家一起成功的方法。", sw: "Kiasili natafuta njia za watu kufanikiwa pamoja.", sv: "Jag letar naturligt efter sätt för människor att lyckas tillsammans.", de: "Ich suche von selbst Wege, wie Menschen gemeinsam Erfolg haben.", pt: "Naturalmente procuro jeitos de as pessoas terem sucesso juntas.", fr: "Je cherche naturellement comment les gens peuvent réussir ensemble." },
  "I enjoy combining different people's strengths.": { es: "Disfruto combinando las fortalezas de distintas personas.", ar: "أستمتع بالجمع بين نقاط قوة أشخاص مختلفين.", zh: "我喜欢把不同人的长处结合起来。", sw: "Ninafurahia kuchanganya uimara wa watu tofauti.", sv: "Jag tycker om att kombinera olika människors styrkor.", de: "Ich kombiniere gern die Stärken verschiedener Menschen.", pt: "Gosto de combinar as forças de pessoas diferentes.", fr: "J'aime combiner les forces de différentes personnes." },
  "I work to make shared goals feel genuinely shared.": { es: "Me esfuerzo para que los objetivos compartidos se sientan realmente compartidos.", ar: "أعمل على جعل الأهداف المشتركة مشتركة حقًا.", zh: "我努力让共同目标真正成为大家的目标。", sw: "Ninafanya kazi ili malengo ya pamoja yahisike kuwa ya pamoja kweli.", sv: "Jag arbetar för att gemensamma mål verkligen ska kännas gemensamma.", de: "Ich arbeite daran, dass gemeinsame Ziele sich wirklich gemeinsam anfühlen.", pt: "Trabalho para que metas compartilhadas sejam sentidas como de todos.", fr: "Je fais en sorte que les objectifs communs soient vraiment partagés." },
  "I often help groups coordinate their efforts.": { es: "A menudo ayudo a los grupos a coordinar sus esfuerzos.", ar: "كثيرًا ما أساعد المجموعات على تنسيق جهودها.", zh: "我常常帮助团队协调工作。", sw: "Mara nyingi nasaidia vikundi kuratibu juhudi zao.", sv: "Jag hjälper ofta grupper att samordna sina insatser.", de: "Ich helfe Gruppen oft, ihre Anstrengungen abzustimmen.", pt: "Muitas vezes ajudo grupos a coordenar seus esforços.", fr: "J'aide souvent les groupes à coordonner leurs efforts." },
  "I value solutions that people can support together.": { es: "Valoro las soluciones que la gente puede apoyar en conjunto.", ar: "أقدّر الحلول التي يمكن للناس دعمها معًا.", zh: "我重视大家都能支持的解决方案。", sw: "Ninathamini suluhisho ambazo watu wanaweza kuziunga mkono pamoja.", sv: "Jag värdesätter lösningar som människor kan ställa sig bakom tillsammans.", de: "Ich schätze Lösungen, die Menschen gemeinsam mittragen können.", pt: "Valorizo soluções que as pessoas podem apoiar juntas.", fr: "J'apprécie les solutions que les gens peuvent soutenir ensemble." },
  "Human Insight": { es: "Comprensión humana", ar: "بصيرة إنسانية", zh: "洞察人心", sw: "Ufahamu wa kibinadamu", sv: "Människokännedom", de: "Menschenkenntnis", pt: "Percepção humana", fr: "Intuition humaine" },
  "You pay close attention to emotions, perspectives and the experience behind people's words.": { es: "Prestas mucha atención a las emociones, las perspectivas y la experiencia que hay detrás de las palabras de la gente.", ar: "تولي اهتمامًا كبيرًا للمشاعر ووجهات النظر والتجربة الكامنة وراء كلام الناس.", zh: "你密切关注情绪、观点，以及人们话语背后的经历。", sw: "Unazingatia kwa makini hisia, mitazamo na uzoefu ulio nyuma ya maneno ya watu.", sv: "Du är mycket uppmärksam på känslor, perspektiv och upplevelsen bakom människors ord.", de: "Du achtest genau auf Gefühle, Sichtweisen und das Erleben hinter den Worten anderer.", pt: "Você presta muita atenção às emoções, perspectivas e à experiência por trás das palavras das pessoas.", fr: "Vous êtes très attentif aux émotions, aux points de vue et au vécu derrière les mots des gens." },
  "Reflect what you think someone is experiencing, then ask whether you understood correctly.": { es: "Expresa lo que crees que alguien está viviendo y luego pregunta si lo entendiste bien.", ar: "اعكس ما تظن أن الشخص يمر به، ثم اسأل إن كنت فهمت بشكل صحيح.", zh: "说出你认为对方正在经历什么，再问自己是否理解正确。", sw: "Eleza unachodhani mtu anapitia, kisha uliza kama ulielewa sawasawa.", sv: "Spegla vad du tror att någon upplever och fråga sedan om du har förstått rätt.", de: "Spiegle, was du glaubst, dass jemand erlebt, und frag dann, ob du richtig verstanden hast.", pt: "Diga o que acha que a pessoa está sentindo e pergunte se entendeu certo.", fr: "Reformulez ce que vous pensez que la personne vit, puis demandez si vous avez bien compris." },
  "Absorbing every emotion can become exhausting. Empathy does not require carrying everything.": { es: "Absorber todas las emociones puede agotar. La empatía no exige cargar con todo.", ar: "قد يكون امتصاص كل المشاعر مرهقًا. التعاطف لا يتطلب حمل كل شيء.", zh: "吸收所有情绪会让人疲惫。共情不等于背负一切。", sw: "Kubeba kila hisia kunaweza kuchosha. Huruma haihitaji kubeba kila kitu.", sv: "Att ta in varje känsla kan bli utmattande. Empati kräver inte att du bär allt.", de: "Jedes Gefühl aufzunehmen kann erschöpfen. Empathie heißt nicht, alles mitzutragen.", pt: "Absorver todas as emoções pode esgotar. Empatia não exige carregar tudo.", fr: "Absorber chaque émotion peut épuiser. L'empathie n'exige pas de tout porter." },
  "I quickly sense how a situation is affecting someone.": { es: "Percibo enseguida cómo una situación está afectando a alguien.", ar: "أشعر بسرعة كيف يؤثر موقف ما في شخص.", zh: "我能很快感觉到某个情况对别人的影响。", sw: "Ninahisi haraka jinsi hali inavyomwathiri mtu.", sv: "Jag känner snabbt av hur en situation påverkar någon.", de: "Ich spüre schnell, wie eine Situation jemanden berührt.", pt: "Percebo rápido como uma situação está afetando alguém.", fr: "Je sens vite comment une situation affecte quelqu'un." },
  "I try to understand the experience behind another person's words.": { es: "Intento entender la experiencia detrás de las palabras de otra persona.", ar: "أحاول فهم التجربة الكامنة وراء كلمات الآخر.", zh: "我努力理解别人话语背后的经历。", sw: "Najaribu kuelewa uzoefu ulio nyuma ya maneno ya mtu mwingine.", sv: "Jag försöker förstå upplevelsen bakom en annan persons ord.", de: "Ich versuche, das Erleben hinter den Worten eines anderen zu verstehen.", pt: "Tento entender a experiência por trás das palavras do outro.", fr: "J'essaie de comprendre le vécu derrière les mots d'une autre personne." },
  "People often feel comfortable telling me what really concerns them.": { es: "La gente suele sentirse cómoda contándome lo que de verdad le preocupa.", ar: "كثيرًا ما يرتاح الناس لإخباري بما يقلقهم حقًا.", zh: "人们常常愿意告诉我他们真正担心的事。", sw: "Watu mara nyingi wanastarehe kuniambia kinachowahangaisha kweli.", sv: "Människor känner sig ofta trygga att berätta för mig vad som verkligen bekymrar dem.", de: "Menschen erzählen mir oft gern, was sie wirklich beschäftigt.", pt: "As pessoas costumam se sentir à vontade para me contar o que realmente as preocupa.", fr: "Les gens se sentent souvent à l'aise pour me dire ce qui les préoccupe vraiment." },
  "I notice emotional shifts in a room.": { es: "Noto los cambios emocionales en una sala.", ar: "ألاحظ التحولات العاطفية في المكان.", zh: "我能察觉房间里的情绪变化。", sw: "Ninagundua mabadiliko ya hisia chumbani.", sv: "Jag märker känslomässiga skiftningar i ett rum.", de: "Ich bemerke Stimmungswechsel in einem Raum.", pt: "Noto mudanças de clima emocional num ambiente.", fr: "Je remarque les changements d'ambiance dans une pièce." },
  "I naturally adapt my support to the person in front of me.": { es: "De forma natural adapto mi apoyo a la persona que tengo delante.", ar: "أكيّف دعمي بطبيعتي مع الشخص الذي أمامي.", zh: "我会自然地根据眼前的人调整支持方式。", sw: "Kiasili narekebisha msaada wangu kulingana na mtu aliye mbele yangu.", sv: "Jag anpassar naturligt mitt stöd efter personen framför mig.", de: "Ich passe meine Unterstützung von selbst an die Person vor mir an.", pt: "Naturalmente adapto meu apoio à pessoa à minha frente.", fr: "J'adapte naturellement mon soutien à la personne en face de moi." },
  "Clear Expression": { es: "Expresión clara", ar: "تعبير واضح", zh: "清晰表达", sw: "Ufafanuzi wazi", sv: "Tydligt uttryck", de: "Klarer Ausdruck", pt: "Expressão clara", fr: "Expression claire" },
  "You translate ideas into language that attracts attention and helps people understand.": { es: "Traduces las ideas a un lenguaje que capta la atención y ayuda a entender.", ar: "تترجم الأفكار إلى لغة تجذب الانتباه وتساعد الناس على الفهم.", zh: "你能把想法转化为吸引注意、帮助理解的语言。", sw: "Unatafsiri mawazo kuwa lugha inayovutia na kusaidia watu kuelewa.", sv: "Du översätter idéer till ett språk som fångar uppmärksamhet och hjälper människor att förstå.", de: "Du übersetzt Ideen in Sprache, die Aufmerksamkeit weckt und Menschen beim Verstehen hilft.", pt: "Você traduz ideias em linguagem que chama atenção e ajuda as pessoas a entender.", fr: "Vous traduisez les idées en un langage qui attire l'attention et aide à comprendre." },
  "Lead with the central message, then choose one example the audience will remember.": { es: "Empieza por el mensaje central y elige un ejemplo que el público recuerde.", ar: "ابدأ بالرسالة الأساسية، ثم اختر مثالًا سيتذكره الجمهور.", zh: "先讲核心信息，再挑一个听众会记住的例子。", sw: "Anza na ujumbe mkuu, kisha chagua mfano mmoja ambao hadhira itaukumbuka.", sv: "Börja med det centrala budskapet och välj sedan ett exempel som publiken kommer ihåg.", de: "Beginne mit der Kernbotschaft und wähle dann ein Beispiel, das sich das Publikum merkt.", pt: "Comece pela mensagem central e escolha um exemplo que o público vai lembrar.", fr: "Commencez par le message central, puis choisissez un exemple que le public retiendra." },
  "A polished message can outrun evidence or listening. Leave space for questions and correction.": { es: "Un mensaje pulido puede ir por delante de las pruebas o de la escucha. Deja espacio para preguntas y correcciones.", ar: "قد تسبق الرسالة المصقولة الأدلة أو الإصغاء. اترك مساحة للأسئلة والتصحيح.", zh: "精雕细琢的说法可能超前于证据或倾听。留出提问和纠正的空间。", sw: "Ujumbe uliong'arishwa unaweza kutangulia ushahidi au kusikiliza. Acha nafasi kwa maswali na marekebisho.", sv: "Ett polerat budskap kan springa före belägg eller lyssnande. Lämna utrymme för frågor och rättelser.", de: "Eine geschliffene Botschaft kann den Belegen oder dem Zuhören davonlaufen. Lass Raum für Fragen und Korrektur.", pt: "Uma mensagem bem polida pode passar à frente das evidências ou da escuta. Deixe espaço para perguntas e correções.", fr: "Un message soigné peut devancer les preuves ou l'écoute. Laissez de la place aux questions et aux corrections." },
  "I enjoy making complicated ideas easy to understand.": { es: "Disfruto haciendo fáciles de entender las ideas complicadas.", ar: "أستمتع بتبسيط الأفكار المعقدة.", zh: "我喜欢把复杂的想法讲得浅显易懂。", sw: "Ninafurahia kufanya mawazo tata yaeleweke kwa urahisi.", sv: "Jag tycker om att göra komplicerade idéer lätta att förstå.", de: "Ich mache gern komplizierte Ideen leicht verständlich.", pt: "Gosto de deixar ideias complicadas fáceis de entender.", fr: "J'aime rendre les idées compliquées faciles à comprendre." },
  "I naturally search for the wording that will connect with an audience.": { es: "De forma natural busco las palabras que conecten con el público.", ar: "أبحث بطبيعتي عن الصياغة التي تصل إلى الجمهور.", zh: "我会自然地寻找能打动听众的措辞。", sw: "Kiasili natafuta maneno yatakayogusa hadhira.", sv: "Jag letar naturligt efter formuleringar som når fram till publiken.", de: "Ich suche von selbst nach Worten, die beim Publikum ankommen.", pt: "Naturalmente procuro as palavras que vão tocar o público.", fr: "Je cherche naturellement les mots qui toucheront le public." },
  "I can usually explain why an idea matters.": { es: "Normalmente sé explicar por qué importa una idea.", ar: "أستطيع عادةً توضيح أهمية الفكرة.", zh: "我通常能讲清楚一个想法为什么重要。", sw: "Kwa kawaida naweza kueleza kwa nini wazo ni muhimu.", sv: "Jag kan oftast förklara varför en idé spelar roll.", de: "Ich kann meist erklären, warum eine Idee wichtig ist.", pt: "Em geral consigo explicar por que uma ideia importa.", fr: "Je sais généralement expliquer pourquoi une idée compte." },
  "I like using examples or stories to make a point memorable.": { es: "Me gusta usar ejemplos o historias para que una idea se recuerde.", ar: "أحب استخدام الأمثلة أو القصص لتبقى الفكرة في الذاكرة.", zh: "我喜欢用例子或故事让观点令人难忘。", sw: "Napenda kutumia mifano au hadithi kufanya hoja ikumbukwe.", sv: "Jag gillar att använda exempel eller berättelser för att göra en poäng minnesvärd.", de: "Ich nutze gern Beispiele oder Geschichten, um etwas einprägsam zu machen.", pt: "Gosto de usar exemplos ou histórias para tornar algo marcante.", fr: "J'aime utiliser des exemples ou des histoires pour rendre un point mémorable." },
  "I feel energised when helping a group understand something clearly.": { es: "Me carga de energía ayudar a un grupo a entender algo con claridad.", ar: "أشعر بالحيوية عندما أساعد مجموعة على فهم شيء بوضوح.", zh: "帮助一群人清楚理解某件事让我充满活力。", sw: "Ninapata nguvu ninaposaidia kikundi kuelewa jambo kwa uwazi.", sv: "Jag får energi av att hjälpa en grupp att förstå något tydligt.", de: "Es gibt mir Energie, einer Gruppe zu helfen, etwas klar zu verstehen.", pt: "Fico cheio de energia ao ajudar um grupo a entender algo com clareza.", fr: "Ça me donne de l'énergie d'aider un groupe à comprendre clairement quelque chose." },
  "Learning Drive": { es: "Impulso de aprendizaje", ar: "شغف التعلم", zh: "学习动力", sw: "Hamu ya kujifunza", sv: "Lärlust", de: "Lernantrieb", pt: "Vontade de aprender", fr: "Soif d'apprendre" },
  "Choose a learning target that immediately supports a real project or challenge.": { es: "Elige un objetivo de aprendizaje que apoye de inmediato un proyecto o reto real.", ar: "اختر هدف تعلم يدعم فورًا مشروعًا أو تحديًا حقيقيًا.", zh: "选择一个能立刻支持真实项目或挑战的学习目标。", sw: "Chagua lengo la kujifunza linalosaidia mara moja mradi au changamoto halisi.", sv: "Välj ett lärandemål som direkt stöder ett verkligt projekt eller en utmaning.", de: "Wähle ein Lernziel, das sofort ein echtes Projekt oder eine echte Herausforderung unterstützt.", pt: "Escolha uma meta de aprendizado que apoie na hora um projeto ou desafio real.", fr: "Choisissez un objectif d'apprentissage qui sert tout de suite un vrai projet ou défi." },
  "Learning can become collection without application. Convert each learning cycle into an experiment.": { es: "Aprender puede convertirse en acumular sin aplicar. Convierte cada ciclo de aprendizaje en un experimento.", ar: "قد يتحول التعلم إلى جمع بلا تطبيق. حوّل كل دورة تعلم إلى تجربة.", zh: "学习可能变成只收集不应用。把每一轮学习都变成一次实验。", sw: "Kujifunza kunaweza kuwa kukusanya bila kutumia. Geuza kila mzunguko wa kujifunza kuwa jaribio.", sv: "Lärande kan bli samlande utan tillämpning. Gör om varje lärcykel till ett experiment.", de: "Lernen kann zum Sammeln ohne Anwendung werden. Mach aus jedem Lernzyklus ein Experiment.", pt: "Aprender pode virar colecionar sem aplicar. Transforme cada ciclo de aprendizado num experimento.", fr: "Apprendre peut devenir collectionner sans appliquer. Transformez chaque cycle d'apprentissage en expérience." },
  "Learning something new gives me energy.": { es: "Aprender algo nuevo me da energía.", ar: "يمنحني تعلم شيء جديد طاقة.", zh: "学习新东西让我充满活力。", sw: "Kujifunza kitu kipya kunanipa nguvu.", sv: "Att lära mig något nytt ger mig energi.", de: "Etwas Neues zu lernen gibt mir Energie.", pt: "Aprender algo novo me dá energia.", fr: "Apprendre quelque chose de nouveau me donne de l'énergie." },
  "I enjoy the process of becoming more capable.": { es: "Disfruto el proceso de volverme más capaz.", ar: "أستمتع بعملية أن أصبح أكثر قدرة.", zh: "我享受变得更有能力的过程。", sw: "Ninafurahia mchakato wa kuwa na uwezo zaidi.", sv: "Jag tycker om processen att bli mer kunnig.", de: "Ich genieße es, immer fähiger zu werden.", pt: "Gosto do processo de ficar mais capaz.", fr: "J'aime le processus qui me rend plus compétent." },
  "I often investigate a subject beyond what is required.": { es: "A menudo investigo un tema más allá de lo necesario.", ar: "كثيرًا ما أبحث في موضوع أبعد مما هو مطلوب.", zh: "我常常超出要求去研究一个主题。", sw: "Mara nyingi nachunguza mada kupita kiasi kinachohitajika.", sv: "Jag fördjupar mig ofta i ett ämne mer än vad som krävs.", de: "Ich vertiefe ein Thema oft über das Nötige hinaus.", pt: "Muitas vezes pesquiso um assunto além do necessário.", fr: "J'approfondis souvent un sujet au-delà de ce qui est demandé." },
  "I seek feedback that can improve my performance.": { es: "Busco opiniones que puedan mejorar mi rendimiento.", ar: "أسعى إلى ملاحظات تحسّن أدائي.", zh: "我主动寻求能提升表现的反馈。", sw: "Natafuta maoni yanayoweza kuboresha utendaji wangu.", sv: "Jag söker feedback som kan förbättra mina prestationer.", de: "Ich suche Rückmeldungen, die meine Leistung verbessern können.", pt: "Busco feedback que possa melhorar meu desempenho.", fr: "Je cherche des retours qui peuvent améliorer ma performance." },
  "I like turning unfamiliar topics into usable knowledge.": { es: "Me gusta convertir temas desconocidos en conocimiento útil.", ar: "أحب تحويل المواضيع غير المألوفة إلى معرفة قابلة للاستخدام.", zh: "我喜欢把陌生的主题变成可用的知识。", sw: "Napenda kugeuza mada zisizojulikana kuwa maarifa yanayotumika.", sv: "Jag gillar att göra obekanta ämnen till användbar kunskap.", de: "Ich mache gern aus unbekannten Themen nutzbares Wissen.", pt: "Gosto de transformar temas desconhecidos em conhecimento útil.", fr: "J'aime transformer des sujets inconnus en savoir utilisable." },
  "Purposeful Commitment": { es: "Compromiso con propósito", ar: "التزام هادف", zh: "目标承诺", sw: "Kujitolea kwa kusudi", sv: "Meningsfullt engagemang", de: "Sinnvolles Engagement", pt: "Compromisso com propósito", fr: "Engagement porteur de sens" },
  "Connect routine tasks to the person, principle or outcome they ultimately serve.": { es: "Conecta las tareas rutinarias con la persona, el principio o el resultado al que sirven en último término.", ar: "اربط المهام الروتينية بالشخص أو المبدأ أو النتيجة التي تخدمها في النهاية.", zh: "把日常任务与它最终服务的人、原则或成果联系起来。", sw: "Unganisha kazi za kawaida na mtu, kanuni au matokeo yanayotumikia hatimaye.", sv: "Koppla rutinuppgifter till den person, princip eller det resultat de ytterst tjänar.", de: "Verbinde Routineaufgaben mit der Person, dem Prinzip oder dem Ergebnis, dem sie letztlich dienen.", pt: "Ligue tarefas de rotina à pessoa, ao princípio ou ao resultado a que elas servem no fim.", fr: "Reliez les tâches routinières à la personne, au principe ou au résultat qu'elles servent au bout du compte." },
  "Strong conviction can become inflexibility. Separate core values from preferred methods.": { es: "Una convicción fuerte puede volverse inflexible. Separa los valores esenciales de los métodos preferidos.", ar: "قد تتحول القناعة القوية إلى تصلّب. افصل القيم الأساسية عن الأساليب المفضلة.", zh: "强烈的信念可能变成固执。把核心价值和偏好的方法区分开。", sw: "Imani thabiti inaweza kuwa ukaidi. Tenganisha maadili ya msingi na mbinu unazopendelea.", sv: "Stark övertygelse kan bli oflexibilitet. Skilj kärnvärden från föredragna metoder.", de: "Starke Überzeugung kann zu Unbeweglichkeit werden. Trenne Grundwerte von bevorzugten Methoden.", pt: "Convicção forte pode virar inflexibilidade. Separe valores essenciais de métodos preferidos.", fr: "Une forte conviction peut devenir rigidité. Séparez les valeurs fondamentales des méthodes préférées." },
  "I work hardest when I understand why the outcome matters.": { es: "Trabajo más cuando entiendo por qué importa el resultado.", ar: "أعمل بأقصى جهد عندما أفهم أهمية النتيجة.", zh: "当我明白结果为何重要时，我工作最努力。", sw: "Ninafanya kazi kwa bidii zaidi ninapoelewa kwa nini matokeo ni muhimu.", sv: "Jag arbetar hårdast när jag förstår varför resultatet spelar roll.", de: "Ich arbeite am härtesten, wenn ich verstehe, warum das Ergebnis zählt.", pt: "Trabalho mais duro quando entendo por que o resultado importa.", fr: "Je travaille le plus dur quand je comprends pourquoi le résultat compte." },
  "My values strongly influence the commitments I make.": { es: "Mis valores influyen mucho en los compromisos que asumo.", ar: "تؤثر قيمي بقوة في الالتزامات التي أقطعها.", zh: "我的价值观深刻影响我所做的承诺。", sw: "Maadili yangu yanaathiri sana ahadi ninazotoa.", sv: "Mina värderingar påverkar starkt vilka åtaganden jag gör.", de: "Meine Werte prägen stark, wozu ich mich verpflichte.", pt: "Meus valores influenciam muito os compromissos que assumo.", fr: "Mes valeurs influencent fortement les engagements que je prends." },
  "I want my effort to contribute to something worthwhile.": { es: "Quiero que mi esfuerzo contribuya a algo que valga la pena.", ar: "أريد أن يسهم جهدي في شيء ذي قيمة.", zh: "我希望我的努力能为有价值的事做出贡献。", sw: "Nataka juhudi zangu zichangie kitu chenye thamani.", sv: "Jag vill att min insats ska bidra till något värdefullt.", de: "Ich will, dass meine Mühe zu etwas Lohnendem beiträgt.", pt: "Quero que meu esforço contribua para algo que valha a pena.", fr: "Je veux que mes efforts contribuent à quelque chose qui en vaut la peine." },
  "I am persistent when a goal feels meaningful.": { es: "Soy constante cuando un objetivo tiene sentido para mí.", ar: "أكون مثابرًا عندما يكون الهدف ذا معنى.", zh: "当目标有意义时，我会坚持不懈。", sw: "Ninadumu lengo linapokuwa na maana.", sv: "Jag är uthållig när ett mål känns meningsfullt.", de: "Ich bin ausdauernd, wenn sich ein Ziel sinnvoll anfühlt.", pt: "Sou persistente quando uma meta parece significativa.", fr: "Je suis persévérant quand un objectif a du sens." },
  "I often evaluate choices by whether they fit a larger purpose.": { es: "A menudo valoro las decisiones según encajen en un propósito mayor.", ar: "كثيرًا ما أقيّم الخيارات بمدى ملاءمتها لغاية أكبر.", zh: "我常常根据是否符合更大的目标来评估选择。", sw: "Mara nyingi napima machaguo kwa kuangalia kama yanaendana na kusudi kubwa zaidi.", sv: "Jag bedömer ofta val efter om de passar ett större syfte.", de: "Ich bewerte Entscheidungen oft danach, ob sie zu einem größeren Zweck passen.", pt: "Muitas vezes avalio escolhas pelo quanto se encaixam num propósito maior.", fr: "J'évalue souvent les choix selon qu'ils servent un but plus large." },
  "Steady Presence": { es: "Presencia serena", ar: "حضور ثابت", zh: "沉稳在场", sw: "Uwepo tulivu", sv: "Stadig närvaro", de: "Ruhige Präsenz", pt: "Presença serena", fr: "Présence posée" },
  "You bring emotional steadiness, patience and perspective when pressure rises.": { es: "Aportas estabilidad emocional, paciencia y perspectiva cuando aumenta la presión.", ar: "تجلب الثبات العاطفي والصبر والمنظور عندما يشتد الضغط.", zh: "压力增大时，你能带来情绪上的稳定、耐心和视野。", sw: "Unaleta utulivu wa hisia, subira na mtazamo shinikizo linapoongezeka.", sv: "Du bidrar med känslomässig stadga, tålamod och perspektiv när trycket ökar.", de: "Du bringst emotionale Stabilität, Geduld und Überblick, wenn der Druck steigt.", pt: "Você traz estabilidade emocional, paciência e perspectiva quando a pressão aumenta.", fr: "Vous apportez stabilité émotionnelle, patience et recul quand la pression monte." },
  "When tension increases, slow the pace enough to identify facts, choices and the next useful action.": { es: "Cuando aumente la tensión, baja el ritmo lo suficiente para identificar los hechos, las opciones y la siguiente acción útil.", ar: "عندما يزداد التوتر، أبطئ الإيقاع بما يكفي لتحديد الحقائق والخيارات والخطوة المفيدة التالية.", zh: "紧张加剧时，放慢节奏，理清事实、选择和下一步有用的行动。", sw: "Mvutano ukiongezeka, punguza kasi vya kutosha kutambua ukweli, machaguo na hatua inayofuata yenye manufaa.", sv: "När spänningen ökar, sakta ner tillräckligt för att se fakta, valmöjligheter och nästa användbara steg.", de: "Wenn die Spannung steigt, verlangsame das Tempo so weit, dass du Fakten, Optionen und den nächsten sinnvollen Schritt erkennst.", pt: "Quando a tensão aumenta, desacelere o bastante para identificar fatos, opções e a próxima ação útil.", fr: "Quand la tension monte, ralentissez assez pour identifier les faits, les options et la prochaine action utile." },
  "Calmness may be mistaken for low urgency or can hide your own needs. Communicate what you care about.": { es: "La calma puede confundirse con poca urgencia u ocultar tus propias necesidades. Comunica lo que te importa.", ar: "قد يُفهم الهدوء على أنه قلة اهتمام بالعجلة أو قد يخفي احتياجاتك. عبّر عما يهمك.", zh: "冷静可能被误认为不着急，也可能掩盖你自己的需求。说出你在乎的事。", sw: "Utulivu unaweza kudhaniwa kuwa ukosefu wa haraka au kuficha mahitaji yako. Eleza unachokijali.", sv: "Lugn kan uppfattas som låg angelägenhet eller dölja dina egna behov. Berätta vad du bryr dig om.", de: "Ruhe kann als geringe Dringlichkeit missverstanden werden oder deine eigenen Bedürfnisse verbergen. Sag, was dir wichtig ist.", pt: "A calma pode ser confundida com pouca urgência ou esconder suas próprias necessidades. Diga o que importa para você.", fr: "Le calme peut passer pour un manque d'urgence ou masquer vos propres besoins. Dites ce qui compte pour vous." },
  "I usually think clearly when pressure rises.": { es: "Normalmente pienso con claridad cuando aumenta la presión.", ar: "أفكر عادةً بوضوح عندما يزداد الضغط.", zh: "压力增大时，我通常能清晰思考。", sw: "Kwa kawaida nafikiri kwa uwazi shinikizo linapoongezeka.", sv: "Jag tänker oftast klart när trycket ökar.", de: "Ich denke meist klar, wenn der Druck steigt.", pt: "Em geral penso com clareza quando a pressão aumenta.", fr: "Je pense généralement clairement quand la pression monte." },
  "My calmness often helps other people settle.": { es: "Mi calma suele ayudar a que otros se tranquilicen.", ar: "كثيرًا ما يساعد هدوئي الآخرين على الاستقرار.", zh: "我的冷静常常能帮助别人平静下来。", sw: "Utulivu wangu mara nyingi husaidia watu wengine kutulia.", sv: "Mitt lugn hjälper ofta andra att landa.", de: "Meine Ruhe hilft anderen oft, sich zu beruhigen.", pt: "Minha calma muitas vezes ajuda os outros a se acalmarem.", fr: "Mon calme aide souvent les autres à s'apaiser." },
  "I can separate an urgent feeling from the next useful action.": { es: "Puedo separar una sensación de urgencia de la siguiente acción útil.", ar: "أستطيع الفصل بين الشعور بالإلحاح والخطوة المفيدة التالية.", zh: "我能把紧迫感与下一步有用的行动区分开。", sw: "Ninaweza kutenganisha hisia ya haraka na hatua inayofuata yenye manufaa.", sv: "Jag kan skilja en känsla av brådska från nästa användbara steg.", de: "Ich kann ein dringendes Gefühl vom nächsten sinnvollen Schritt trennen.", pt: "Consigo separar uma sensação de urgência da próxima ação útil.", fr: "Je sais séparer un sentiment d'urgence de la prochaine action utile." },
  "I recover perspective quickly after a setback.": { es: "Recupero la perspectiva rápido tras un revés.", ar: "أستعيد منظوري بسرعة بعد أي انتكاسة.", zh: "遭遇挫折后，我能很快恢复视角。", sw: "Ninarejesha mtazamo haraka baada ya kikwazo.", sv: "Jag återfår snabbt perspektivet efter ett bakslag.", de: "Nach einem Rückschlag gewinne ich schnell wieder Überblick.", pt: "Recupero a perspectiva rápido depois de um revés.", fr: "Je retrouve vite du recul après un revers." },
  "I tend to respond deliberately rather than react immediately.": { es: "Tiendo a responder con calma en lugar de reaccionar de inmediato.", ar: "أميل إلى الاستجابة بتروٍّ بدلًا من رد الفعل الفوري.", zh: "我倾向于深思熟虑地回应，而不是立即反应。", sw: "Ninaelekea kujibu kwa makini badala ya kuitikia mara moja.", sv: "Jag brukar svara eftertänksamt i stället för att reagera direkt.", de: "Ich antworte eher überlegt, statt sofort zu reagieren.", pt: "Costumo responder com calma em vez de reagir na hora.", fr: "J'ai tendance à répondre de façon réfléchie plutôt qu'à réagir aussitôt." },
  "Choice": { es: "Elección", ar: "الاختيار", zh: "选择", sw: "Chaguo", sv: "Val", de: "Auswahl", pt: "Escolha", fr: "Choix" },
  "Build my report": { es: "Crear mi informe", ar: "أنشئ تقريري", zh: "生成我的报告", sw: "Tengeneza ripoti yangu", sv: "Skapa min rapport", de: "Meinen Bericht erstellen", pt: "Montar meu relatório", fr: "Créer mon rapport" }
});
